(function(root){
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const groups=[{keys:['estoque','material','produto','compra','peca'],name:'estoque',tools:['Registros e planilhas','Conferências e inspeções','Indicadores e relatórios'],action:'registrar entradas e saídas por item, definir estoque mínimo e conferir divergências',question:'Qual item costuma faltar e quem registra suas movimentações?'},{keys:['agenda','retorno','visita','cliente','ligacao','venda'],name:'atendimento comercial',tools:['Agendamentos e retornos','Assistente de atendimento','Indicadores e relatórios'],action:'centralizar contatos, registrar o responsável e organizar retornos por prazo',question:'Os retornos são organizados por pessoa, por empresa ou por serviço?'},{keys:['servico','prazo','etapa','equipe','obra','manutencao','entrega'],name:'execução de serviços',tools:['Serviços e etapas','Conferências e inspeções','Indicadores e relatórios'],action:'acompanhar cada serviço por etapa, responsável e prazo, com conferência ao concluir',question:'Em qual etapa o serviço costuma ficar parado?'},{keys:['documento','nota','pedido','texto','relatorio','formulario'],name:'documentos e registros',tools:['Extração de informações','Registros e planilhas'],action:'conferir os campos extraídos antes de alimentar uma planilha com o registro aprovado',question:'Quais campos precisam aparecer no registro final?'}];
function diagnose(text,sector='Serviços',turn=0){const n=normalize(text);const matches=groups.filter(g=>g.keys.some(k=>n.includes(k)));if(!text.trim())return{body:'Descreva uma dificuldade da sua empresa para experimentar o diagnóstico.',tools:[]};if(!matches.length)return{body:`Para o cenário de ${sector.toLowerCase()}, falta um exemplo concreto para sugerir ferramentas com segurança.\n\nConte qual tarefa é feita hoje, quem a executa e onde ocorre a demora ou o erro.`,tools:[]};const names=matches.map(g=>g.name).join(' e ');const openings=[`Pelo que você descreveu, o ponto de atenção está em ${names}.`,`Sua descrição aponta uma oportunidade de melhorar ${names}.`,`Eu começaria pelo fluxo de ${names}, no cenário de ${sector.toLowerCase()}.`];const all=[...new Set(matches.flatMap(g=>g.tools))];return{body:`${openings[turn%openings.length]}\n\n${matches.map((g,i)=>`${i+1}. ${g.action[0].toUpperCase()+g.action.slice(1)}.`).join('\n')}\n\nFerramentas para combinar: ${all.join(' + ')}.\n\n${n.includes('manual')||n.includes('papel')?'Comece substituindo um único registro manual e confira o resultado antes de expandir.':'Valide o fluxo com uma pequena equipe antes de aplicar em toda a operação.'}\n\n${matches[turn%matches.length].question}`,tools:all}}
function extract(text){const capture=rx=>(text.match(rx)||[])[1]?.trim()||'Não informado';return{empresa:capture(/(?:empresa|fornecedor|cliente)\s*[:=-]\s*([^\n;]+)/i),documento:capture(/(?:nota|pedido|documento)\s*(?:n[ºo°.]*)?\s*[:#=-]?\s*(\d[\w/-]*)/i),valor:capture(/(?:total|valor)\s*[:=-]?\s*(?:R\$\s*)?([\d.,]+)/i),prazo:capture(/(?:prazo|data|entrega)\s*[:=-]\s*([^\n;]+)/i)}}
function reply(text,context,turn){const n=normalize(text);const lead=['Claro.','Vamos organizar isso.','Consigo orientar esse pedido.'][turn%3];if(/preco|valor|custa|orcamento/.test(n))return `${lead} Para ${context.toLowerCase()}, o orçamento depende do escopo e das informações do pedido. Descreva o que precisa e a quantidade. Nesta demonstração, nenhum preço comercial é calculado.`;if(/prazo|quando|entrega|demora/.test(n))return `${lead} No cenário de ${context.toLowerCase()}, preciso da data desejada e do serviço solicitado para verificar disponibilidade. Qual é a sua data de preferência?`;if(/cancel|problema|reclam|atras/.test(n))return `${lead} Registre o número do pedido, o que aconteceu e o melhor contato para retorno. O caso seria direcionado ao responsável por ${context.toLowerCase()}, com acompanhamento até a resolução.`;if(/ola|oi|bom dia|boa tarde/.test(n))return `${lead} Bem-vindo ao atendimento de ${context.toLowerCase()}. Você precisa de orçamento, informação sobre prazos ou ajuda com um pedido?`;return `${lead} Sobre “${text.slice(0,160)}”, no atendimento de ${context.toLowerCase()}, preciso entender o pedido e seu objetivo. ${turn%2?'Já existe um pedido ou você deseja iniciar uma solicitação?':'Qual resultado você espera e qual prazo precisa atender?'}`}
const api={normalize,diagnose,extract,reply};root.HorizonEngine=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
